'use client';

/*
 * Consent preferences (Radix UI), "zeste" style — generated by `zeste add`, yours to edit.
 * Nothing is pre-checked: a service the user has not chosen is treated as refused.
 */
import { Dialog, Label, Switch } from 'radix-ui';
import { useZeste } from '@zeste/react';
import type { Messages } from '@zeste/services/i18n/types';
import './theme.css';

const focus = 'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--zeste-ink)';
const button = `inline-flex items-center justify-center rounded-full border-[1.5px] border-(--zeste-ink) bg-(--zeste-ink) px-[18px] py-2.5 text-sm font-semibold text-(--zeste-paper) transition hover:opacity-90 ${focus}`;
const save = `inline-flex items-center justify-center rounded-full bg-(--zeste-accent) px-[18px] py-2.5 text-sm font-semibold text-(--zeste-on-accent) transition hover:opacity-90 ${focus}`;

export function CookiePreferences() {
  const zeste = useZeste<Messages>();
  const t = zeste.messages;

  return (
    <Dialog.Root open={zeste.preferencesOpen} onOpenChange={zeste.setPreferencesOpen}>
      <Dialog.Portal>
        <Dialog.Overlay data-zeste-skin="zeste" className="fixed inset-0 z-50 bg-(--zeste-scrim)" />
        <Dialog.Content
          data-zeste-skin="zeste"
          className="fixed top-1/2 left-1/2 z-50 grid max-h-[85vh] w-[calc(100%-2rem)] max-w-lg -translate-x-1/2 -translate-y-1/2 gap-4 overflow-y-auto rounded-[22px] bg-(--zeste-paper) p-6 text-(--zeste-ink) shadow-[0_30px_80px_rgb(0_0_0/0.3)]"
        >
          <Dialog.Title className="pr-8 text-xl font-bold">{t.title}</Dialog.Title>
          <Dialog.Description className="text-sm leading-relaxed text-(--zeste-soft)">{t.disclaimer}</Dialog.Description>

          {zeste.categories.map((category) => (
            <section
              key={category.key}
              className="grid gap-2 border-t border-(--zeste-line) pt-3"
              aria-labelledby={`zeste-category-${category.key}`}
            >
              <h3 id={`zeste-category-${category.key}`} className="text-sm font-semibold">
                {t.categories[category.key]?.title ?? category.key}
              </h3>
              <p className="text-sm text-(--zeste-soft)">{t.categories[category.key]?.details}</p>
              <ul className="grid gap-3 pt-1">
                {category.services.map((service) => (
                  <li key={service.key} className="flex items-center justify-between gap-4">
                    <div className="text-sm">
                      <Label.Root htmlFor={`zeste-service-${service.key}`} className="font-medium">
                        {service.name}
                      </Label.Root>
                      {service.privacyUrl && (
                        <a
                          href={service.privacyUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="block text-(--zeste-soft) underline underline-offset-2 hover:text-(--zeste-ink)"
                        >
                          {t.privacyUrl}{' '}
                          <span className="sr-only">
                            {service.name} {t.newWindow}
                          </span>
                        </a>
                      )}
                    </div>
                    <Switch.Root
                      id={`zeste-service-${service.key}`}
                      checked={zeste.draft[service.key] ?? false}
                      onCheckedChange={(checked) => zeste.setDraft(service.key, checked)}
                      className={`inline-flex h-[26px] w-11 shrink-0 cursor-pointer items-center rounded-full bg-(--zeste-track) p-[3px] transition data-[state=checked]:bg-(--zeste-switch-on) ${focus}`}
                    >
                      <Switch.Thumb className="block size-5 rounded-full bg-white shadow transition data-[state=checked]:translate-x-[18px] data-[state=checked]:bg-(--zeste-thumb-on)" />
                    </Switch.Root>
                  </li>
                ))}
              </ul>
            </section>
          ))}

          {zeste.exempt.length > 0 && (
            <p className="border-t border-(--zeste-line) pt-3 text-sm text-(--zeste-soft)">
              <span className="font-semibold text-(--zeste-ink)">{t.mandatoryTitle}</span> :{' '}
              {zeste.exempt.map((s) => s.name).join(', ')}
            </p>
          )}

          <div className="flex flex-wrap items-center gap-2 pt-2">
            <button type="button" className={button} {...zeste.actions.denyAll}>
              {t.denyAll}
            </button>
            <button type="button" className={button} {...zeste.actions.acceptAll}>
              {t.acceptAll}
            </button>
            <button type="button" className={`${save} ml-auto`} {...zeste.actions.savePreferences}>
              {t.save}
            </button>
          </div>

          <Dialog.Close
            className={`absolute top-5 right-5 grid size-8 place-items-center rounded-full text-(--zeste-soft) hover:bg-(--zeste-line) hover:text-(--zeste-ink) ${focus}`}
            aria-label={t.close}
          >
            <span aria-hidden="true">✕</span>
          </Dialog.Close>
        </Dialog.Content>
      </Dialog.Portal>
    </Dialog.Root>
  );
}
